create extension if not exists pgcrypto;
create table if not exists public.phone_numbers (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,twilio_sid text unique,phone_number text not null unique,country_code text not null check(country_code ~ '^[A-Z]{2}$'),number_type text not null check(number_type in ('local','mobile','tollFree')),capabilities jsonb not null default '{}'::jsonb,status text not null check(status in ('pending','active','failed','released')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists phone_numbers_user_status_idx on public.phone_numbers(user_id,status);alter table public.phone_numbers enable row level security;create policy "Users can read their own numbers" on public.phone_numbers for select to authenticated using ((select auth.uid())=user_id);grant select on public.phone_numbers to authenticated;
create or replace function public.reserve_phone_number(p_user_id uuid,p_phone_number text,p_country_code text,p_number_type text,p_capabilities jsonb,p_max integer) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_count integer;v_id uuid; begin perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));select count(*) into v_count from public.phone_numbers where user_id=p_user_id and status in ('active','pending');if v_count>=p_max then raise exception 'number_limit';end if;insert into public.phone_numbers(user_id,phone_number,country_code,number_type,status,capabilities) values(p_user_id,p_phone_number,p_country_code,p_number_type,'pending',p_capabilities) returning id into v_id;return v_id;end $$;
revoke all on function public.reserve_phone_number(uuid,text,text,text,jsonb,integer) from public,anon,authenticated;grant execute on function public.reserve_phone_number(uuid,text,text,text,jsonb,integer) to service_role;
create table if not exists public.messages (id uuid primary key default gen_random_uuid(),twilio_sid text not null unique,user_id uuid not null references auth.users(id) on delete cascade,from_number text not null,to_number text not null,body text not null default '',direction text not null check(direction in ('inbound','outbound')),status text not null,error_code text,date_created timestamptz not null default now());
create index if not exists messages_user_date_idx on public.messages(user_id,date_created desc);create index if not exists messages_thread_idx on public.messages(user_id,from_number,to_number,date_created desc);alter table public.messages enable row level security;create policy "Users can read their own messages" on public.messages for select to authenticated using ((select auth.uid())=user_id);grant select on public.messages to authenticated;
create table if not exists public.call_events (call_sid text primary key,user_id uuid not null references auth.users(id) on delete cascade,status text not null,direction text,from_number text,to_number text,duration_seconds integer,updated_at timestamptz not null default now());create index if not exists call_events_user_date_idx on public.call_events(user_id,updated_at desc);alter table public.call_events enable row level security;create policy "Users can read their own call events" on public.call_events for select to authenticated using((select auth.uid())=user_id);grant select on public.call_events to authenticated;
create table if not exists public.sms_opt_outs(user_id uuid not null references auth.users(id) on delete cascade,from_number text not null,recipient text not null,source_message_sid text,created_at timestamptz not null default now(),primary key(user_id,from_number,recipient));alter table public.sms_opt_outs enable row level security;
create table if not exists public.kyc_submissions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','approved','rejected','needs_information')),documents jsonb not null default '[]'::jsonb,review_note text,twilio_address_sid text,twilio_compliance_complete boolean not null default false,reviewed_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists kyc_user_created_idx on public.kyc_submissions(user_id,created_at desc);alter table public.kyc_submissions enable row level security;create policy "Users can read their own KYC status" on public.kyc_submissions for select to authenticated using ((select auth.uid())=user_id);grant select on public.kyc_submissions to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('kyc-private','kyc-private',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['image/jpeg','image/png','image/webp','application/pdf'];
create policy "Users upload KYC files into own folder" on storage.objects for insert to authenticated with check(bucket_id='kyc-private' and (storage.foldername(name))[1]=(select auth.uid())::text);create policy "Users read their own KYC files" on storage.objects for select to authenticated using(bucket_id='kyc-private' and (storage.foldername(name))[1]=(select auth.uid())::text);
